function main({ currentTime, cutoverTime, securityTime }) {
 let isSecurityPeriod = false;
 let isEmergencyCutover = false;
 let isCutoverStart = false;

 let securityStartTime = "";
 let securityEndTime = "";

 try {
 // 当前时间：去掉星期部分
 const currentTimeStr = currentTime.split(" ").slice(0, 2).join(" ");
 const current = new Date(currentTimeStr.replace(" ", "T"));

 let cutoverStart = null;
 let cutoverEnd = null;

 // 解析割接时间
 if (cutoverTime && cutoverTime.includes("/")) {
 const [startStr, endStr] = cutoverTime.split("/");

 cutoverStart = new Date(startStr.trim().replace(" ", "T"));
 cutoverEnd = new Date(endStr.trim().replace(" ", "T"));
 }

 // ========================
 // 判断割接窗口是否与重保时间重叠
 // ========================
 if (
 securityTime &&
 securityTime.includes("/") &&
 cutoverStart &&
 cutoverEnd
 ) {
 const [securityStartStr, securityEndStr] = securityTime.split("/");

 securityStartTime = securityStartStr.trim();
 securityEndTime = securityEndStr.trim();

 const securityStart = new Date(securityStartTime.replace(" ", "T"));
 const securityEnd = new Date(securityEndTime.replace(" ", "T"));

 // 只要割接窗口和重保窗口有交集，就认为命中重保
 isSecurityPeriod =
 cutoverStart.getTime() <= securityEnd.getTime() &&
 cutoverEnd.getTime() >= securityStart.getTime();
 }

 // 非重保期间才判断割接状态
 if (!isSecurityPeriod && cutoverStart && cutoverEnd) {
 // 距离割接开始时间是否在 72 小时内
 const diffHours =
 (cutoverStart.getTime() - current.getTime()) / (1000 * 60 * 60);

 isEmergencyCutover =
 diffHours >= 0 &&
 diffHours <= 72;

 // 当前时间是否处于割接窗口
 isCutoverStart =
 current.getTime() >= cutoverStart.getTime();
 }
 } catch (e) {
 isSecurityPeriod = false;
 isEmergencyCutover = false;
 isCutoverStart = false;
 securityStartTime = ""; // 修复：原来误写成未声明的 security_start_time
 securityEndTime = "";
 }

 // ========================
 // 生成割接场景（优先级：重保期 > 已在窗口内 > 紧急割接 > 正常割接）
 // ========================
 let cutover_scene = "normal";
 if (isSecurityPeriod) {
 cutover_scene = "major_event";
 } else if (isCutoverStart) {
 cutover_scene = "in_window";
 } else if (isEmergencyCutover) {
 cutover_scene = "emergency";
 }

 return {
 is_security_period: isSecurityPeriod,
 security_start_time: securityStartTime,
 security_end_time: securityEndTime,
 is_emergency_cutover: isEmergencyCutover,
 is_cutover_start: isCutoverStart,
 cutover_scene: cutover_scene
 };
}

