function main({ data }) {
 // 初始化一个空数组用于存储所有图片链接
 let allImages = [];

 // 检查data是否存在且包含result数组
 if (data && Array.isArray(data)) {
 // 遍历result数组中的每个文件对象
 data.forEach(file => {
 // 如果文件对象包含images数组，则将其中的所有图片链接添加到allImages数组中
 if (file && Array.isArray(file.images)) {
 allImages = allImages.concat(file.images);
 }
 });
 }

 // 返回包含合并后图片数组的对象
 return {
 allImages: allImages
 };
}

